(function($){'use strict';if(malisafiTracking.propertyId>0){let startTime=Date.now();let maxScroll=0;let galleryViewed=false;let mapViewed=false;$(window).on('scroll',function(){const scrollTop=$(window).scrollTop();const docHeight=$(document).height()-$(window).height();const scrollPercent=Math.round((scrollTop / docHeight)* 100);if(scrollPercent>maxScroll){maxScroll=scrollPercent;}});$('.property-gallery,.property-slider,.gallery-item').on('click',function(){galleryViewed=true;});$('.property-map,#property-map,.map-container').on('click',function(){mapViewed=true;});$('.contact-agent,.send-inquiry,.phone-number,.email-agent').on('click',function(){$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_interaction',nonce:malisafiTracking.nonce,property_id:malisafiTracking.propertyId,interaction_type:'contact_clicked',data:{button:$(this).attr('class')}});const currentDuration=Math.round((Date.now()-startTime)/ 1000);$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_view_duration',nonce:malisafiTracking.nonce,property_id:malisafiTracking.propertyId,duration:currentDuration,scroll_depth:maxScroll,gallery_viewed:galleryViewed,map_viewed:mapViewed});});$('a[href^="tel:"]').on('click',function(){$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_interaction',nonce:malisafiTracking.nonce,property_id:malisafiTracking.propertyId,interaction_type:'phone_click'});});$('a[href^="mailto:"]').on('click',function(){$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_interaction',nonce:malisafiTracking.nonce,property_id:malisafiTracking.propertyId,interaction_type:'email_click'});});$('a[href*="wa.me"],a[href*="whatsapp"]').on('click',function(){$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_interaction',nonce:malisafiTracking.nonce,property_id:malisafiTracking.propertyId,interaction_type:'whatsapp_click'});});$('.share-button,.social-share').on('click',function(){const shareMethod=$(this).data('network')||$(this).attr('class').match(/facebook|twitter|whatsapp|email/)?.[0]||'unknown';$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_interaction',nonce:malisafiTracking.nonce,property_id:malisafiTracking.propertyId,interaction_type:'share_social',data:{method:shareMethod}});});$(window).on('beforeunload',function(){const duration=Math.round((Date.now()-startTime)/ 1000);if(navigator.sendBeacon){const formData=new FormData();formData.append('action','malisafi_track_view_duration');formData.append('nonce',malisafiTracking.nonce);formData.append('property_id',malisafiTracking.propertyId);formData.append('duration',duration);formData.append('scroll_depth',maxScroll);formData.append('gallery_viewed',galleryViewed ? 1:0);formData.append('map_viewed',mapViewed ? 1:0);navigator.sendBeacon(malisafiTracking.ajaxurl,formData);}else{$.ajax({url:malisafiTracking.ajaxurl,type:'POST',async:false,data:{action:'malisafi_track_view_duration',nonce:malisafiTracking.nonce,property_id:malisafiTracking.propertyId,duration:duration,scroll_depth:maxScroll,gallery_viewed:galleryViewed,map_viewed:mapViewed}});}});setInterval(function(){const currentDuration=Math.round((Date.now()-startTime)/ 1000);$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_view_duration',nonce:malisafiTracking.nonce,property_id:malisafiTracking.propertyId,duration:currentDuration,scroll_depth:maxScroll,gallery_viewed:galleryViewed,map_viewed:mapViewed});},30000);}$('.wizard-form,.malisafi-property-submit-form').each(function(){const $form=$(this);let formStartTime=Date.now();$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_funnel',nonce:malisafiTracking.nonce,section:'form_loaded',field:'initial',has_value:1});$form.on('blur',':input',function(){const $step=$(this).closest('.wizard-step');const $section=$(this).closest('.form-section');const sectionTitle=$step.length ? $step.find('h2,h3').first().text().trim():$section.find('.form-section-title,h3,h2').first().text().trim();const fieldName=$(this).attr('name')||$(this).attr('id');const hasValue=$(this).val()? 1:0;$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_funnel',nonce:malisafiTracking.nonce,section:sectionTitle,field:fieldName,has_value:hasValue});});$form.on('submit',function(){const timeSpent=Math.round((Date.now()-formStartTime)/ 1000);$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_funnel',nonce:malisafiTracking.nonce,section:'submit_attempt',field:'form_submit',has_value:1,time_spent:timeSpent});});});$(document).on('click','.favorite-button,.add-to-favorites',function(e){e.preventDefault();const $button=$(this);const propertyId=$button.data('property-id')||malisafiTracking.propertyId;$.post(malisafiTracking.ajaxurl,{action:'malisafi_track_interaction',nonce:malisafiTracking.nonce,property_id:propertyId,interaction_type:'favorite'});$button.toggleClass('favorited');});})(jQuery);